CREATE TABLE IF NOT EXISTS public.asset_movement_email_deliveries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, device_id uuid NOT NULL, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, recorded_at timestamptz NOT NULL, sent_at timestamptz NOT NULL DEFAULT now(), UNIQUE (user_id, device_id, recorded_at)); GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.asset_movement_email_deliveries TO service_role; ALTER TABLE public.asset_movement_email_deliveries ENABLE ROW LEVEL SECURITY;